.filter-caption {
    color: white;
    font-family: monospace;
    font-size: small;
    line-height: 1.1;
    position: absolute;
    text-shadow: -1px -1px 0 #000,
     1px -1px 0 #000,
    -1px  1px 0 #000,
     1px  1px 0 #000;
}

div[data-primitive] .pair {
    display: flex;
    flex-direction: column-reverse;
    margin-bottom: 1em;
}

div[data-primitive] .shape {
    flex: 0 0 auto;
    height: 250px;
    width: 100%;
}

div[data-primitive] .desc {
    flex: 1 1 auto;
    min-width: 0;
    padding: 1em;
    word-wrap: break-word;
}

div[data-primitive] .desc code {
    white-space: normal;
}

div[data-primitive] .input {
    display: inline-block;
    user-select: none;
}

div[data-primitive] .input::before {
    content: " ";
}

div[data-primitive] .input input[type=range] {
    width: 200px;
}

div[data-primitive] .input>div {
    display: inline-block;
    position: absolute;
}

div[data-primitive] .input input {
    position: absolute;
}

div[data-primitive] .input input[type=text] {
    background: #444;
    border: none;
    color: white;
    padding: 3px;
}

@media (max-width: 600px) {
    div[data-primitive] .input>div {
        right: 0;
    }

}

@media (max-width: 600px) {
    div[data-primitive] .input input {
        opacity: 0.2;
        right: 1em;
    }

}

@media (max-width: 550px) {
